-- ROLLBACK for mobile-app/supabase/migrations/0145_java_lesson_rewrite_batch01.sql (twin admin-panel/supabase/migrations/116_java_lesson_rewrite_batch01.sql).
-- Generated by scripts/build-java-seed.mjs. NOT a migration: this folder is outside
-- supabase/migrations, so the CLI never applies it. Run it by hand, once, in one transaction.
--
-- Puts the 20 lesson bodies and short_descriptions back to the original
-- 0047_seed_java_tutorial_content.sql text, but only where they still hold this batch's text (a later admin edit
-- is left alone and reported). Removes the 19 Practice Problems blocks this batch added and the
-- 19 mock tests with their MCQs. Deleting a mock test also deletes students' attempts on it;
-- the count is printed first. Topics, bookmarks and progress are never touched.
-- Safe to run twice: the second run finds nothing and changes nothing.
-- ----------------------------------------------------------------------------
do $rollback$
declare
  v_attempts int; v_n int;
begin
  select count(*) into v_attempts from public.test_attempts where test_id in ('pt-java-hashmap', 'pt-java-arraylist', 'pt-java-collection-framework', 'pt-java-stream-api', 'pt-java-lambda-expressions', 'pt-java-constructors', 'pt-java-inheritance', 'pt-java-polymorphism', 'pt-java-abstraction', 'pt-java-interface', 'pt-java-abstract-class', 'pt-java-static-keyword', 'pt-java-this-keyword', 'pt-java-method-overloading', 'pt-java-method-overriding', 'pt-java-string', 'pt-java-exception', 'pt-java-try-catch', 'pt-java-thread');
  raise notice 'rollback: removing 19 mock test(s) if present; this deletes % test attempt(s).', v_attempts;
  delete from public.practice_tests where id in ('pt-java-hashmap', 'pt-java-arraylist', 'pt-java-collection-framework', 'pt-java-stream-api', 'pt-java-lambda-expressions', 'pt-java-constructors', 'pt-java-inheritance', 'pt-java-polymorphism', 'pt-java-abstraction', 'pt-java-interface', 'pt-java-abstract-class', 'pt-java-static-keyword', 'pt-java-this-keyword', 'pt-java-method-overloading', 'pt-java-method-overriding', 'pt-java-string', 'pt-java-exception', 'pt-java-try-catch', 'pt-java-thread');   -- cascades test_questions, test_attempts
  delete from public.learning_contents c using public.learning_topics t
   where t.id = c.topic_id and t.source_kind = 'java_tutorial' and t.source_ref in ('collections-framework/hashmap', 'collections-framework/arraylist', 'collections-framework/collection-framework', 'advanced-java/stream-api', 'advanced-java/lambda-expressions', 'object-oriented-programming/constructors', 'object-oriented-programming/inheritance', 'object-oriented-programming/polymorphism', 'object-oriented-programming/abstraction', 'object-oriented-programming/interface', 'object-oriented-programming/abstract-class', 'object-oriented-programming/static-keyword', 'object-oriented-programming/this-keyword', 'object-oriented-programming/method-overloading', 'object-oriented-programming/method-overriding', 'arrays-and-strings/string', 'packages-and-exception-handling/exception', 'packages-and-exception-handling/try-catch', 'multithreading/thread')
     and c.metadata ->> 'source' = 'java_practice_seed' and c.metadata ->> 'origin' = 'java_lesson_rewrite';
  get diagnostics v_n = row_count;
  raise notice 'rollback: removed % practice block(s).', v_n;
end
$rollback$;

-- HashMap: restore the original text where this batch's text is still in place
with src(old_body, old_descr, new_md5, new_descr_md5) as (values ($jr687$## 1. What is HashMap?

`HashMap` is the most commonly used implementation of the `Map` interface. It stores key-value pairs and does not guarantee any particular order of the entries.

## 2. Why is it used?

`HashMap` provides very fast lookup, insertion, and deletion of key-value pairs on average, making it a go-to choice whenever quick access using a key is needed and order doesn't matter.

## 3. Real-Life Example

Think of a large filing cabinet where each drawer is labeled with a unique code, and you can jump directly to the right drawer using that code, without checking every drawer one by one. `HashMap` gives this same kind of quick, direct access using keys.

## 4. Syntax

```java
HashMap<KeyType, ValueType> mapName = new HashMap<>();
```

## 5. Example Program

```java
import java.util.HashMap;

public class HashMapDemo {
    public static void main(String[] args) {
        HashMap<String, Integer> marks = new HashMap<>();
        marks.put("Rahul", 85);
        marks.put("Sneha", 90);
        System.out.println(marks);
    }
}
```

**Output:**
```
{Rahul=85, Sneha=90}
```
*(Note: HashMap does not guarantee this exact order every time.)*

## 6. Key Points to Remember

- `HashMap` allows one `null` key and multiple `null` values.
- Iteration order is not guaranteed and may vary.
- `HashMap` is not synchronized, so it's not automatically thread-safe.$jr687$,
  $jr688$HashMap is the most commonly used implementation of the Map interface. It stores key-value pairs and does not guarantee any particular order of the entries.$jr688$, '50cf9f5408282ff0dc1a752dd627a454', '6a05cdb265aeb245612599a4c618bca5')),
